const fs = require('fs');
const path = require('path');

/**
 * Regenerates src/fonts.css from the installed @fontsource packages.
 *
 *   node scripts/generate-fonts-css.cjs
 *
 * Why a generated file rather than importing the packages' CSS directly:
 * Fontsource's per-subset stylesheets carry no unicode-range, so stacking two
 * subsets of one family (latin + latin-ext, which city names like İzmir need)
 * leaves the cascade ambiguous. Its per-weight combined stylesheets do carry
 * unicode-range, but declare every subset — cyrillic, greek, vietnamese and the
 * rest — so importing those would emit far more files than the app can use.
 * This takes the combined files' unicode-range values verbatim and keeps only
 * the subsets and weights listed below, and only the woff2 source: the .woff
 * fallback Fontsource lists alongside it would add ~1 MB that no WebView this
 * app runs in will ever request.
 *
 * Run it again after bumping a @fontsource package.
 */

// Family -> subsets and weights actually used. Mirrors what the old Google
// stylesheet requested, minus subsets nobody needs.
// stylesheet requested, minus subsets nobody needs (cyrillic, greek, vietnamese).
const WANT = {
  ubuntu:               { subsets: ['latin', 'latin-ext'],      weights: [400, 500, 700] },
  inter:                { subsets: ['latin', 'latin-ext'],      weights: [400, 500, 600, 700] },
  'cormorant-garamond': { subsets: ['latin'],                   weights: [400, 500, 600, 700] },
  'jetbrains-mono':     { subsets: ['latin'],                   weights: [300, 400, 500, 600] },
  amiri:                { subsets: ['arabic', 'latin'],         weights: [400, 700] },
};

const out = [];
let missing = [];
for (const [pkg, { subsets, weights }] of Object.entries(WANT)) {
  const dir = path.join('node_modules/@fontsource', pkg);
  for (const weight of weights) {
    const combined = fs.readFileSync(path.join(dir, `${weight}.css`), 'utf8');
    for (const subset of subsets) {
      const marker = `/* ${pkg}-${subset}-${weight}-normal */`;
      const start = combined.indexOf(marker);
      if (start < 0) { missing.push(`${pkg}/${subset}/${weight}`); continue; }
      const end = combined.indexOf('}', start);
      let block = combined.slice(start + marker.length, end + 1).trim();
      // Keep woff2 only: every WebView this app runs in supports it, and the
      // .woff fallback Fontsource lists alongside would ship ~1 MB nobody fetches.
      const woff2 = block.match(/url\((\.\/files\/[^)]+\.woff2)\)\s*format\('woff2'\)/);
      if (!woff2) { missing.push(`no-woff2 ${pkg}/${subset}/${weight}`); continue; }
      block = block.replace(/src:[^;]+;/, `src: url('@fontsource/${pkg}/${woff2[1].slice(2)}') format('woff2');`);
      out.push(block);
    }
  }
}
if (missing.length) { console.error('MISSING:', missing.join(', ')); process.exit(1); }
const cssHeader = `/* Generated by scripts/generate-fonts-css.cjs — do not edit by hand.
   Self-hosted webfonts, woff2 only, unicode-range copied verbatim from the
   @fontsource combined stylesheets. See that script for why. */\n\n`;
fs.writeFileSync('src/fonts.css', cssHeader + out.join('\n\n') + '\n');
console.log('wrote src/fonts.css with', out.length, 'faces');
